<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Holder\ThemeAssetContentAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeAssetContentAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ThemeAssetContentAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getContent returns null on a freshly created holder.
     */
    public function testContentNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithThemeAssetContentAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isContentAssigned());
        $this->assertNull($holder->getContent());
    }
}
class ImplWithThemeAssetContentAttributeHolderUnitTest
{
    use ThemeAssetContentAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedContentRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultContent();
    }
}
